# -*- coding: utf-8 --

from robot.api import logger
import os
from taf.rfrl.cbts.connections.rest_conn_vcu import GenericCU
from taf.rfrl.cbts.utilities import generic_utils

LOG_HEAD = LOG_END = '*' * 8


class vCUSnapshot(GenericCU):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def trigger_and_save_vcu_local_snapshot(self, snapshot_dir=None, save_ongoing_snapshot=True, conn_alias='default'):
        """Triggering local snapshot collection and save the snapshot files to the given folder.
        If the folder is not given, one default directory constructed with the ROBOT OUTPUT_DIR,
        TEST_NAME and timestamp will be created. The keyword will be stuck until the snapshot collection finished.

        :param str snapshot_dir:
        :param save_ongoing_snapshot: If set to True, the current ongoing snapshot will be saved and will not trigger a new snapshot collection.
                                      If set to False, an exception will be raised if an ongoing local snapshot is existed.
                                      Default is True.
        :param conn_alias:
        :return str: The compressed snapshot file path or the snapshot file folder if snapshot files are not compressed.
        """
        if snapshot_dir:
            snapshot_log_folder = snapshot_dir
        else:
            snapshot_log_folder = generic_utils.generate_log_path_with_log_type(log_type='vcu_snapshot')

        snapshot_status = self.cu.check_snapshot_status(connection=conn_alias)

        if snapshot_status == 'idle':
            logger.info('{} Start collecting vdu local snapshot... {}'.format(LOG_HEAD, LOG_END))
            self.cu.get_local_snapshot(directory=snapshot_log_folder, connection=conn_alias)

        if save_ongoing_snapshot and snapshot_status == 'local-ongoing':
            logger.info(
                '{} There is already a local ongoing snapshot collection, the current snapshot files will be saved {}'.format(
                    LOG_HEAD, LOG_END))
            snapshot_ope_id = self.cu.get_snapshot_operations_information(connection=conn_alias)['operation_id']
            self.cu.get_local_snapshot_by_id(directory=snapshot_log_folder,
                                             operation_id=snapshot_ope_id,
                                             connection=conn_alias)

        if save_ongoing_snapshot is False and snapshot_status == 'local-ongoing':
            raise AssertionError("""There is an ongoing snapshot collection, new snapshot collection can not be triggered.
            If you want to save the current ongoing snapshot, set the param - save_ongoing_snapshot to True""")

        files = os.listdir(snapshot_log_folder)
        if len(files) == 0:
            raise AssertionError('No snapshot files found in local after saving snapshot operation!')
        snapshot_log_file = os.path.join(snapshot_log_folder, files[0])
        return snapshot_log_file

    def trigger_vdu_local_snapshot_collection(self, conn_alias='default'):
        """Just trigger vdu local snapshot collection, but not saving it.

        :param conn_alias:
        :return:
        """
        snapshot_status = self.cu.check_snapshot_status(connection=conn_alias)
        if snapshot_status == 'idle':
            operation_id = self.cu.trigger_local_snapshot(connection=conn_alias)
            return operation_id
        #  TODO: save the current ongoing snapshot but not raise an exception
        raise AssertionError('There is an ongoing snapshot collection')

    def save_local_snapshot(self, snapshot_dir='', operation_id='', conn_alias='default'):
        """
        Saving local snapshot file triggered by the given operation id to the given folder.
        If the operation id is not given, the current ongoing snapshot if existed will be saved.
        If the folder is not given, one default directory constructed with the ROBOT OUTPUT_DIR,
        TEST_NAME and timestamp will be created

        :param snapshot_dir:
        :param operation_id:
        :param conn_alias:
        :return:
        """
        if snapshot_dir:
            snapshot_log_folder = snapshot_dir
        else:
            snapshot_log_folder = generic_utils.generate_log_path_with_log_type(log_type='snapshot')

        if operation_id:
            snapshot_ope_id = operation_id
        else:
            snapshot_info = self.cu.get_snapshot_operations_information(connection=conn_alias)
            if len(snapshot_info) != 0:
                snapshot_ope_id = snapshot_info['operation_id']
            else:
                raise Exception('NO ongoing local snapshot collection, trigger it firstly.')

        self.cu.get_local_snapshot_by_id(directory=snapshot_log_folder,
                                         operation_id=snapshot_ope_id,
                                         connection=conn_alias)

        files = os.listdir(snapshot_log_folder)
        if len(files) == 0:
            raise AssertionError('No snapshot files found in local after saving snapshot operation!')
        snapshot_log_file = os.path.join(snapshot_log_folder, files[0])
        return snapshot_log_file
